Q: How can one make an ordered list in HTML/CSS with sub-lists with combined number/letter identifiers? A: <p>You could work with 2 counters, one for letters &amp; one for numbers.</p>

<p><div class="snippet" data-lang="js" data-hide="true" data-console="true" data-babel="false">
<div class="snippet-code snippet-currently-hidden">
<pre class="snippet-code-css lang-css prettyprint-override"><code>ul{
  padding:0;
  list-style-type: none;
}
.root {
  counter-reset: numbers;
}
.root &gt; li::before {
  counter-increment: numbers;
  content: counter(numbers) ". ";
}
.root ul {
  padding-left: 15px;
  counter-reset: letters;
}
.root ul &gt; li::before {
  counter-increment: letters;
  content: counter(numbers) counter(letters, lower-alpha) ". ";
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;ul class="root"&gt;
  &lt;li&gt;item&lt;/li&gt;
  &lt;li&gt;item&lt;/li&gt;
  &lt;li&gt;item
    &lt;ul&gt;
      &lt;li&gt;sub-item&lt;/li&gt;
      &lt;li&gt;sub-item&lt;/li&gt;
      &lt;li&gt;sub-item&lt;/li&gt;
    &lt;/ul&gt;
  &lt;/li&gt;
  &lt;li&gt;item&lt;/li&gt;
  &lt;li&gt;item
    &lt;ul&gt;
      &lt;li&gt;sub-item&lt;/li&gt;
      &lt;li&gt;sub-item&lt;/li&gt;
      &lt;li&gt;sub-item&lt;/li&gt;
    &lt;/ul&gt;
  &lt;/li&gt;
  &lt;li&gt;item&lt;/li&gt;
  &lt;li&gt;item&lt;/li&gt;
  &lt;li&gt;item
    &lt;ul&gt;
      &lt;li&gt;sub-item&lt;/li&gt;
      &lt;li&gt;sub-item&lt;/li&gt;
      &lt;li&gt;sub-item&lt;/li&gt;
    &lt;/ul&gt;
  &lt;/li&gt;
&lt;/ul&gt;</code></pre>
</div>
</div>
</p>

<p>With SASS:</p>

<pre><code>ul{
  padding:0;
  list-style-type: none;
}

.root {
  counter-reset: numbers;
  &gt; li::before {
    counter-increment: numbers;
    content: counter(numbers) ". ";
  }
  ul {
    padding-left: 15px;
    counter-reset: letters;
    &gt; li::before {
      counter-increment: letters;
      content: counter(numbers) counter(letters, lower-alpha) ". ";
    }
  }
}
</code></pre>

Q: snprintf with unknown size of the char[] A: <p>C doesn't work like your typical high-level language.
You are required to alloc every bit of memory you want to use (either be it on the stack or on the heap). That's why on the internet people usually do stuff like <code>char str[100]</code>: they are saying: I'm not expecting a string longer than 99 characters (+ '\0' char at the end of the string).</p>

<p>If you want your typical Java <code>string</code>, you need to create it yourself from scratch. Here's a demo of an implementation with no-so-good performances. variadic string api is left to the reader :)</p>

<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdbool.h&gt;
#include &lt;string.h&gt;

struct string_t {
    ///number of bytes of the string (\0 included)
    size_t capacity;
    ///strlen of the string
    size_t len;
    ///pointer to the actual string
    char* str;
};

struct string_t* newString(const char* str);
void initString(struct string_t* this);
void destroyString(const struct string_t* this);
bool isEmpty(const struct string_t* this);
void tryExpand(struct string_t* this, size_t additionalSpace);
char* getNullTerminatorAddress(const struct string_t* this);
void setString(struct string_t* this, const char* other);

struct string_t* newString(const char* str) {
    struct string_t* result = malloc(sizeof(struct string_t));
    if (result == NULL) {
        fprintf(stderr, "error!\n");
        exit(1);
    }
    initString(result);
    setString(result, str);
    return result;
}

void initString(struct string_t* this) {
    this-&gt;len = 0;
    this-&gt;capacity;
    this-&gt;str = 0;
}

void destroyString(const struct string_t* this) {
    if (this-&gt;str != NULL) {
        free((char*)this-&gt;str);
    }
    free((char*)this);
}

bool isEmpty(const struct string_t* this) {
    return this-&gt;len == 0;
}

void tryExpand(struct string_t* this, size_t additionalSpace) {
    if ((this-&gt;len + additionalSpace) &gt; this-&gt;capacity) {
        if (this-&gt;str != NULL) {
            int newcapacity = this-&gt;len + additionalSpace;
            this-&gt;str = realloc(this-&gt;str, newcapacity);
            this-&gt;capacity = newcapacity;
        } else {
            this-&gt;str = malloc(sizeof(char) * additionalSpace);
            if (this-&gt;str == NULL) {
                exit(1);
            }
        }
    }
}

void trySetting(struct string_t* this, size_t spaceRequired) {
    if ((spaceRequired) &gt; this-&gt;capacity) {
        if (this-&gt;str != NULL) {
            int newcapacity = spaceRequired;
            this-&gt;str = realloc(this-&gt;str, newcapacity);
            this-&gt;capacity = newcapacity;
        } else {
            this-&gt;str = malloc(sizeof(char) * spaceRequired);
            if (this-&gt;str == NULL) {
                exit(1);
            }
            this-&gt;capacity = spaceRequired;
        }
    }
}

char* getNullTerminatorAddress(const struct string_t* this) {
    if (this-&gt;str != NULL) {
        return &amp;this-&gt;str[this-&gt;len];
    } else {
        exit(2);
    }
}

void setString(struct string_t* this, const char* other) {
    int alen = strlen(other);
    trySetting(this, alen + 1);
    //beware of buffer overrun
    strcpy(this-&gt;str, other);
    this-&gt;len = alen;
}

void appendString(struct string_t* this, const char* other) {
    int alen = strlen(other);
    tryExpand(this, alen + 1);
    //beware of buffer overrun
    strcpy(getNullTerminatorAddress(this), other);
    this-&gt;len += alen;
}

void appendInt(struct string_t* this, int other) {
    int bytes = snprintf( NULL, 0, "%d", other); //0 not considered
    tryExpand(this, bytes + 1);
    snprintf(getNullTerminatorAddress(this), bytes+1, "%d", other);
    this-&gt;len += bytes;
}

const char* getString(const struct string_t* this) {
    return (const char*)this-&gt;str;
}

int getLength(const struct string_t* this) {
    return this-&gt;len;
}

int getCapacity(const struct string_t* this) {
    return this-&gt;capacity;
}

int main() {
    int points = 5;
    int total = 10;
    struct string_t* str = newString("You have ");
    appendInt(str, points);
    appendString(str, " points (total: ");
    appendInt(str, total);
    appendString(str, ")");

    printf("%s\n", getString(str));
    destroyString(str);
    return 0;
}

</code></pre>

<p>Note you can retrieve the number of bytes to write in <code>snprintf</code> thanks to the trick of <a href="https://stackoverflow.com/a/32819876/1887602">user2622016</a></p>
